//! 🧪️ IFC2x3 neutral declaration controls and own mutation/inverse authority.
use super::*;
use semio_s_artifact_stdio_contract::part21::Part21Document;
use protocol::ColdMutation;
fn fixture()->semio_framework_pack_json::Value{semio_framework_pack_json::parse(include_str!("🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn path(index:usize)->Vec<P>{vec![P::Key("document".into()),P::Key("instances".into()),P::Index(0),P::Key("entities".into()),P::Index(0),P::Key("arguments".into()),P::Index(index)]}
fn wall()->Ifc2x3Snapshot{Ifc2x3Snapshot{document:Part21Document{instances:vec![Part21Instance{id:1,entities:vec![("IFCWALL".into(),vec![V::Str("0123456789012345678901".into()),V::Unset,V::Str("Wall".into()),V::Real(Part21Decimal{negative:true,coefficient:"12345678901234567890123456789".into(),scale:14,exponent:Some(-200)}),V::Unset,V::Unset,V::Unset,V::Unset])]},Part21Instance{id:u64::MAX,entities:vec![("IFCLOCALPLACEMENT".into(),Vec::new())]}],..Default::default()},..Default::default()}}
#[test]
fn neutral_ifc2x3_declarations_drive_the_real_provider(){let fixture=fixture();assert_eq!(catalog::ifc2x3_attribute_declarations("IFCWALL").unwrap().len(),fixture["wallAttributes"].as_u64().unwrap()as usize);assert!(catalog::ifc2x3_is_subtype("IFCPROJECT","IFCOBJECT"));for row in fixture["cases"].as_array().unwrap(){let name=row["entity"].as_str().unwrap();let attributes=catalog::ifc2x3_attribute_declarations(name).unwrap();let index=row["index"].as_u64().unwrap()as usize;let mut values=vec![V::Unset;attributes.len()];if let Some(members)=row.get("enum"){values[index]=V::Enum(members[0].as_str().unwrap().into());}if row["derived"].as_bool()==Some(true){values[index]=V::Derived;}let snapshot=Ifc2x3Snapshot{document:Part21Document{instances:vec![Part21Instance{id:1,entities:vec![(name.into(),values)]}],..Default::default()},..Default::default()};let provider=Ifc2x3DetailsProvider::new(&snapshot);assert_eq!(provider.presentation(&path(index),Locale::En).unwrap().label,row["attribute"].as_str().unwrap());if row["derived"].as_bool()==Some(true){let mut payload=path(index);payload.push(P::Key("value".into()));assert!(!provider.item_capabilities(&payload).edit);}if let Some(members)=row.get("enum"){let mut payload=path(index);payload.push(P::Key("value".into()));assert_eq!(provider.enum_values(&payload),members.as_array().unwrap().iter().map(|member|DslValue::String(member.as_str().unwrap().into())).collect::<Vec<_>>());}}}
#[test]
fn exact_references_use_own_instances_preserve_decimal_and_restore_central_inverse(){let snapshot=wall();let event=SnapshotEditEvent::SetValue{path:"/document/instances/0/entities/0/arguments/5/reference".into(),value:DslValue::String(u64::MAX.to_string())};assert!(details_edit_is_admitted(&event,&snapshot));let mutations=details_edit_special(&event,&snapshot).unwrap().unwrap();let Ifc2x3Mutation::UpsertInstance(change)=&mutations[0]else{panic!("IFC2x3 reference must keep its own instance primitive")};assert_eq!(change.instance.entities[0].1[5],V::Ref(u64::MAX));assert_eq!(change.instance.entities[0].1[3],snapshot.document.instances[0].entities[0].1[3]);let mut next=snapshot.clone();let mut inverses=Vec::new();for mutation in mutations{inverses.splice(0..0,mutation.inverse(&next).unwrap());next=protocol::apply_diff_cold(mutation.diff(&next).diff(),&next).unwrap();}for mutation in inverses{next=protocol::apply_diff_cold(mutation.diff(&next).diff(),&next).unwrap();}assert_eq!(next,snapshot);let required=SnapshotEditEvent::SetValue{path:"/document/instances/0/entities/0/arguments/1/reference".into(),value:DslValue::String(String::new())};assert!(details_edit_special(&required,&snapshot).is_err());}
#[test]
fn own_type_switch_and_every_original_target_planning_stop_remain_controlled(){let snapshot=wall();let event=SnapshotEditEvent::SetValue{path:"/document/instances/0/entities/0/typeName".into(),value:DslValue::String("IFCDOOR".into())};let mutations=details_edit_special(&event,&snapshot).unwrap().unwrap();let Ifc2x3Mutation::UpsertInstance(change)=&mutations[0]else{panic!("type switch must use own instance")};assert_eq!(change.instance.id,1);assert_eq!(change.instance.entities[0].0,"IFCDOOR");assert_eq!(change.instance.entities[0].1[0],snapshot.document.instances[0].entities[0].1[0]);assert_eq!(change.instance.entities[0].1[2],snapshot.document.instances[0].entities[0].1[2]);let reference=SnapshotEditEvent::SetValue{path:"/document/instances/0/entities/0/arguments/5/reference".into(),value:DslValue::String(u64::MAX.to_string())};let mut work=0;details_edit_special_controlled(&reference,&snapshot,&mut ||{work+=1;Ok(())}).unwrap();for stop in 1..=work{let mut count=0;assert!(details_edit_special_controlled(&reference,&snapshot,&mut ||{count+=1;if count==stop{Err("cancelled".into())}else{Ok(())}}).is_err());}}
#[test]
fn actual_editor_context_uses_its_original_cancellation_and_fuel(){use semio_s_artifact_stdio_contract::editing::SnapshotEditingEditor;use semio_framework_plugin::app_testing::OriginalWorkFixture;type Editor=crate::editor::ifc2x3_any::Ifc2x3AnyEditor;let snapshot=wall();let event=SnapshotEditEvent::SetValue{path:"/document/instances/0/entities/0/arguments/5/reference".into(),value:DslValue::String(u64::MAX.to_string())};for (fuel,cancelled,admitted)in [(0,false,false),(1,false,false),(10000,true,false),(10000,false,true)]{let mut caller=OriginalWorkFixture::new();if cancelled{caller.cancel().cancel_now();}let result=caller.work_turn(OriginalWorkFixture::stock(),fuel,|cx|Editor::snapshot_edit_emit_in_context(&event,&snapshot,cx).map_err(Into::into));assert_eq!(result.is_ok(),admitted);caller.finish();}}

#[test]
fn neutral_set_reference_replacement_cannot_duplicate_an_existing_target(){let row=fixture()["uniqueness"].clone();let snapshot=Ifc2x3Snapshot{document:Part21Document{instances:vec![Part21Instance{id:1,entities:vec![(row["entity"].as_str().unwrap().into(),vec![V::List(vec![V::Ref(2),V::Ref(3)])])]},Part21Instance{id:2,entities:vec![("IFCSIUNIT".into(),Vec::new())]},Part21Instance{id:3,entities:vec![("IFCSIUNIT".into(),Vec::new())]}],..Default::default()},..Default::default()};let event=SnapshotEditEvent::SetValue{path:format!("/document/instances/0/entities/0/arguments/{}/values/{}/reference",row["index"].as_u64().unwrap(),row["replaceIndex"].as_u64().unwrap()),value:DslValue::String(row["duplicateTarget"].as_str().unwrap().into())};assert!(details_edit_special(&event,&snapshot).is_err());}

#[test]
fn raw_numeric_reference_payloads_never_bypass_exact_target_admission(){let mut snapshot=wall();snapshot.document.instances[0].entities[0].1[5]=V::Ref(u64::MAX);for id in [0,1,u64::MAX]{let event=SnapshotEditEvent::SetValue{path:"/document/instances/0/entities/0/arguments/5/value".into(),value:DslValue::uint(id)};assert!(!details_edit_is_admitted(&event,&snapshot));assert!(details_edit_special(&event,&snapshot).is_err());}}

fn domain_expression(value:&semio_framework_pack_json::Value)->Expr{Expr{kind:value["kind"].as_str().unwrap().into(),name:value.get("name").and_then(|value|value.as_str()).map(str::to_owned),width:value.get("width").and_then(|value|value.as_i64()),fixed:value.get("fixed").and_then(|value|value.as_bool()).unwrap_or(false),aggregate:value.get("aggregate").and_then(|value|value.as_str()).map(str::to_owned),lower:value.get("lower").and_then(|value|value.as_i64()),upper:value.get("upper").and_then(|value|value.as_i64()),unique:value.get("unique").and_then(|value|value.as_bool()).unwrap_or(false),optional:value.get("optional").and_then(|value|value.as_bool()).unwrap_or(false),item:value.get("item").map(domain_expression).map(Box::new),..Default::default()}}
fn domain_value(value:&semio_framework_pack_json::Value)->V{match value["kind"].as_str().unwrap(){"unset"=>V::Unset,"derived"=>V::Derived,"int"=>V::Int(value["value"].as_str().unwrap().parse().unwrap()),"ref"=>V::Ref(value["value"].as_str().unwrap().parse().unwrap()),"str"=>V::Str(value["value"].as_str().unwrap().into()),"enum"=>V::Enum(value["value"].as_str().unwrap().into()),"binary"=>V::Binary(value["value"].as_str().unwrap().into()),"list"=>V::List(value["values"].as_array().unwrap().iter().map(domain_value).collect()),"typed"=>V::Typed{name:value["typeName"].as_str().unwrap().into(),items:value["values"].as_array().unwrap().iter().map(domain_value).collect()},"real"=>{let number=&value["value"];V::Real(Part21Decimal{negative:number["negative"].as_bool().unwrap(),coefficient:number["coefficient"].as_str().unwrap().into(),scale:number["scale"].as_u64().unwrap()as u32,exponent:number.get("exponent").and_then(|value|value.as_i64()).map(|value|value as i32)})},_=>panic!("Unknown own Part21 neutral value")}}
#[test]
fn own_part21_domains_and_exact_numeric_equality_use_neutral_vectors(){let fixture=fixture();for row in fixture["structured"]["cases"].as_array().unwrap(){let expression=domain_expression(&row["expression"]);let value=domain_value(&row["value"]);let mut ticks=0;let mut tick=||{ticks+=1;Ok(())};let mut reference=|id:u64,expected:&str,tick:&mut dyn FnMut()->Result<(),String>|{for target in fixture["structured"]["targets"].as_array().unwrap(){tick()?;if target["id"].as_str().unwrap().parse::<u64>().unwrap()==id{return Ok(target["types"].as_array().unwrap().iter().any(|name|catalog::ifc2x3_is_subtype(name.as_str().unwrap(),expected)));}}Ok(false)};let result=domain::check_value(catalog::ifc2x3_catalog(),&expression,&value,false,true,&mut domain::DomainControl{tick:&mut tick,reference:&mut reference});assert_eq!(result.is_ok(),row["admitted"].as_bool().unwrap(),"{}",row["name"].as_str().unwrap());for stop in 1..=ticks{let mut count=0;let mut tick=||{count+=1;if count==stop{Err("original-cancel".into())}else{Ok(())}};assert_eq!(domain::check_value(catalog::ifc2x3_catalog(),&expression,&value,false,true,&mut domain::DomainControl{tick:&mut tick,reference:&mut reference}).unwrap_err(),"original-cancel");}}for row in fixture["structured"]["numbers"].as_array().unwrap(){let integer=V::Int(row["integer"].as_str().unwrap().parse().unwrap());let real=V::Real(Part21Decimal{negative:row["real"]["negative"].as_bool().unwrap(),coefficient:row["real"]["coefficient"].as_str().unwrap().into(),scale:row["real"]["scale"].as_u64().unwrap()as u32,exponent:row["real"].get("exponent").and_then(|value|value.as_i64()).map(|value|value as i32)});let mut tick=||Ok(());let mut reference=|_:u64,_:&str,_:&mut dyn FnMut()->Result<(),String>|Ok(false);assert_eq!(domain::equal(catalog::ifc2x3_catalog(),&named("NUMBER"),&integer,&real,&mut domain::DomainControl{tick:&mut tick,reference:&mut reference}).unwrap(),row["equal"].as_bool().unwrap());}}
#[test]
fn own_part21_context_refuses_raw_enum_and_derived_values_without_publication(){use semio_s_artifact_stdio_contract::editing::SnapshotEditingEditor;use semio_framework_plugin::app_testing::OriginalWorkFixture;type Editor=crate::editor::ifc2x3_any::Ifc2x3AnyEditor;let snapshot=Ifc2x3Snapshot{document:Part21Document{instances:vec![Part21Instance{id:1,entities:vec![("IFCSIUNIT".into(),vec![V::Derived,V::Enum("LENGTHUNIT".into()),V::Unset,V::Enum("METRE".into())])]}],..Default::default()},..Default::default()};let original=snapshot.clone();for derived in [false,true]{let event=if derived{SnapshotEditEvent::SetValue{path:"/document/instances/0/entities/0/arguments/0".into(),value:V::Int(1).to_value()}}else{SnapshotEditEvent::SetValue{path:"/document/instances/0/entities/0/arguments/3/value".into(),value:DslValue::String("BANANA".into())}};let mut caller=OriginalWorkFixture::new();let result=caller.work_turn(OriginalWorkFixture::stock(),1_000_000,|cx|Editor::snapshot_edit_emit_in_context(&event,&snapshot,cx).map_err(Into::into));assert!(result.is_err());assert_eq!(snapshot,original);caller.finish();}}
#[test]
fn own_part21_coordinate_repair_keeps_exact_decimal_and_central_inverse(){let decimal=Part21Decimal{negative:false,coefficient:"123456789012345678901234567890".into(),scale:18,exponent:Some(9)};let snapshot=Ifc2x3Snapshot{document:Part21Document{instances:vec![Part21Instance{id:1,entities:vec![("IFCCARTESIANPOINT".into(),vec![V::List(vec![V::Real(decimal.clone())])])]}],..Default::default()},..Default::default()};let event=SnapshotEditEvent::InsertValue{path:"/document/instances/0/entities/0/arguments/0/values/1".into(),value:V::Real(Part21Decimal{negative:false,coefficient:"1".into(),scale:0,exponent:None}).to_value()};let mutations=details_edit_special(&event,&snapshot).unwrap().unwrap();let mut next=snapshot.clone();let mut inverses=Vec::new();for mutation in mutations{inverses.splice(0..0,mutation.inverse(&next).unwrap());next=protocol::apply_diff_cold(mutation.diff(&next).diff(),&next).unwrap();}assert!(matches!(&next.document.instances[0].entities[0].1[0],V::List(items)if items[0]==V::Real(decimal)));for mutation in inverses{next=protocol::apply_diff_cold(mutation.diff(&next).diff(),&next).unwrap();}assert_eq!(next,snapshot);}

#[test]
fn own_part21_neutral_aggregate_repairs_use_the_shared_domain_interface(){let fixture=fixture();for row in fixture["structured"]["repairs"].as_array().unwrap(){let values=|field:&str|V::List(row[field].as_array().unwrap().iter().map(|value|match value.as_str().unwrap(){"invalid"=>V::Str("invalid".into()),value=>V::Int(value.parse().unwrap())}).collect());let expression=Expr{kind:"aggregate".into(),aggregate:Some(row["aggregate"].as_str().unwrap().into()),lower:row.get("lower").and_then(|value|value.as_i64()),upper:row.get("upper").and_then(|value|value.as_i64()),item:Some(Box::new(named("INTEGER"))),..Default::default()};let indices:Vec<_>=row["route"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize).collect();let operation=match row["operation"].as_str().unwrap(){"insert"=>domain::ValueChange::Insert,"remove"=>domain::ValueChange::Remove,"move"=>domain::ValueChange::Move,_=>domain::ValueChange::Set};let mut tick=||Ok(());let mut reference=|_:u64,_:&str,_:&mut dyn FnMut()->Result<(),String>|Ok(false);assert_eq!(domain::check_change(catalog::ifc2x3_catalog(),&expression,&values("before"),&values("after"),&indices,operation,false,&mut domain::DomainControl{tick:&mut tick,reference:&mut reference}).is_ok(),row["admitted"].as_bool().unwrap(),"{}",row["name"].as_str().unwrap());}}

#[test]
fn exact_part21_decimal_cursor_resumes_neutral_domains_without_binary64_conversion(){let fixture=fixture();let population=Ifc2x3Snapshot{document:Part21Document{instances:fixture["structured"]["targets"].as_array().unwrap().iter().map(|target|Part21Instance{id:target["id"].as_str().unwrap().parse().unwrap(),entities:target["types"].as_array().unwrap().iter().map(|name|(name.as_str().unwrap().into(),Vec::new())).collect()}).collect(),..Default::default()},..Default::default()};for row in fixture["structured"]["cases"].as_array().unwrap(){let expression=Box::leak(Box::new(domain_expression(&row["expression"])));let value=domain_value(&row["value"]);let mut cursor=domain_cursor::DomainCursor::default();cursor.start(expression,&[],domain::ValueChange::Set,false,true,false).unwrap();let mut completed=false;let mut admitted=true;for _ in 0..100_000{match cursor.advance(catalog::ifc2x3_catalog(),&V::Unset,&value,&population){Ok(true)=>{completed=true;break;},Ok(false)=>{},Err(_)=>{admitted=false;completed=true;break;}}}assert!(completed);assert_eq!(admitted,row["admitted"].as_bool().unwrap(),"{}",row["name"].as_str().unwrap());cursor.clear();}}
